<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;minecraft:iron_helmet&quot;</span></span>
